WITH valid AS (SELECT id, country, city, rating, LOWER(country) AS country_lower FROM suppliers WHERE city IS DISTINCT FROM 'Tokyo' AND country = 'SG'), filtered AS (SELECT *, CASE WHEN rating >= 4.4 THEN 'High' WHEN rating >= 2.6 THEN 'Medium' ELSE 'Low' END AS rating_level, COALESCE(city, 'N/A') AS city_filled FROM valid WHERE city IS NOT NULL), with_latest AS (SELECT s.*, top1.product_stock_qty FROM filtered s LEFT JOIN LATERAL (SELECT c.stock_qty AS product_stock_qty FROM products c WHERE c.supplier_id = s.id ORDER BY c.launch_date DESC, c.id DESC LIMIT 1) top1 ON TRUE), scored AS (SELECT *, AVG(product_stock_qty) OVER w_ordered AS country_avg_product_stock_qty, COUNT(product_stock_qty) OVER w_ordered AS country_count_product_stock_qty FROM with_latest WHERE country = 'UK' WINDOW w_ordered AS (PARTITION BY country)), scored_suppliers AS (SELECT id, country, product_stock_qty, country_avg_product_stock_qty, country_count_product_stock_qty, SUM(rating) OVER (ORDER BY country_avg_product_stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_rating, LEAD(rating, 1) OVER (PARTITION BY country ORDER BY country_avg_product_stock_qty, id) AS next_rating, ROUND(rating / SUM(rating) OVER (PARTITION BY city), 4) AS rating_share FROM scored) SELECT CASE WHEN country_avg_product_stock_qty >= 379 THEN 'PREMIUM' ELSE 'STANDARD' END AS country_avg_product_stock_qty_tier, country, COUNT(CASE WHEN country = 'DE' THEN 1 END) AS de_count, COUNT(CASE WHEN country = 'JP' THEN 1 END) AS jp_count, APPROX_PERCENTILE(rating_share, 0.9) AS rating_share_p90, ROUND(SUM(running_rating) / NULLIF(COUNT(CASE WHEN country = 'SG' THEN 1 END), 0), 2) AS running_rating_per_sg FROM scored_suppliers GROUP BY GROUPING SETS ((CASE WHEN country_avg_product_stock_qty >= 379 THEN 'PREMIUM' ELSE 'STANDARD' END, country), (CASE WHEN country_avg_product_stock_qty >= 379 THEN 'PREMIUM' ELSE 'STANDARD' END), ()) ORDER BY country_avg_product_stock_qty_tier;
